"use strict";(self.webpackChunk_N_E=self.webpackChunk_N_E||[]).push([[57279],{57279:function(n){n.exports=JSON.parse('{"content":"\\n<center>\\n<BookCard \\n          cover=\\"/assets/snippets/books/three-body-2.png\\"\\n          title=\\"삼체 2: 암흑의 숲\\"\\n          author=\\"류츠신\\"\\n          publisher=\\"자음과 모음\\"\\n          publishedDate=\\"2022-02-15\\"\\n          isbn=\\"9788954442701\\"\\n          rating=5\\n          tags=\\"SF\\"\\n        />\\n</center>\\n\\n## Review\\n1편을 읽고 바로 읽기 시작한 2편.  \\n이번은 1편보다 더욱 두껍다. 내가 읽었던 소설 책 중에 가장 두꺼웠을 수도..\\n<br>\\n인류가 처한 위기를 극복하기 위해 전 세계가 고민을 한다.  \\n하지만 모든 걸 알고 있고 기술적인 방해를 하고 있는 <mark>그것</mark>의 존재 때문에 희망은 없어 보인다.\\n<br>\\n인류가 거만해지는 장면들이 나오는데, 이미 결말이 보였었다.  \\n<br>\\n만약 내가 그 당시 인류였다면, 어떤 마음으로 살아가고 있었을까?  \\n내가 살고 있는 세대에는 큰 문제 없이 지금처럼 살 수 있으니까 크게 신경 안 쓸 거 같다는 생각이 든다.  \\n역시 나는 인류애가 없...  \\n그리고 막연히 결국 누군가 해답을 찾겠지 하며 큰 변화 없이 살았을 거 같다.  \\n<br>\\n이미 결말이 났는데 삼체 3편은 무슨 내용이지?"}')}}]);